/// What the lexer could not do at the error position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LexErrorReason {
    /// No rule matches.
    NoMatch,
    /// A rule matches, but its value does not fit the Rust type (a numeral beyond `u64`).
    Unrepresentable,
    /// End of input inside a nested mode.
    EndInMode,
    /// The input is longer than `u32::MAX` bytes.
    TooLong,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LexError {
    /// Character offset, as in Lean's `LexError.pos`.
    pub pos: usize,
    /// Byte offset.
    pub byte_pos: usize,
    /// The offending character; none at end of input.
    pub ch: Option<char>,
    pub reason: LexErrorReason,
}

fn lex_error(src: &str, byte_pos: usize, reason: LexErrorReason) -> LexError {
    LexError {
        pos: src[..byte_pos].chars().count(),
        byte_pos,
        ch: src[byte_pos..].chars().next(),
        reason,
    }
}

/// `lpg_kernel::lex` with this lexer's tables: the tokens of `src`, with the terminal
/// `TERM_HOOK` for the rules whose terminal depends on the text.
pub fn lex(src: &[u8], out: &mut Vec<Token>) -> Result<(), lpg_kernel::LexFail> {
    lpg_kernel::lex(src, out, &LEX_CLASS, &LEX_TRANS, &LEX_ACCEPT, LEX_START, LEX_ACCEPT_FROM,
        &RULE_TERM, EOF)
}

