/// The last token pushed is the end-of-input token. A token has no value; `token_value`
/// rebuilds it from the source text of its span. The loop is `lpg_kernel::lex`; the
/// terminals that depend on the text, and the values that may not fit their Rust
/// type, are computed after it, and the first error in the source is reported.
pub fn tokenize(src: &str, out: &mut Vec<Token>) -> Result<(), LexError> {
    let first = out.len();
    let res = lex(src.as_bytes(), out);
    for i in first..out.len() {
        let t = &mut out[i];
        let text = &src[t.start as usize..t.end as usize];
        let ok = match t.rule {
            2 => match crate::hooks::keyword_or_identifier(text) { Some(tok) => { t.term = tok.term(); true } None => false },
            3 => lexrt::to_nat(text).is_some(),
            4 => crate::hooks::strip_string_quotes(text).is_some(),
            _ => true,
        };
        if !ok {
            let at = t.start as usize;
            out.truncate(i);
            return Err(lex_error(src, at, LexErrorReason::Unrepresentable));
        }
    }
    match res {
        Ok(()) => Ok(()),
        Err(lpg_kernel::LexFail::NoMatch(pos)) => Err(lex_error(src, pos, LexErrorReason::NoMatch)),
        Err(lpg_kernel::LexFail::TooLong) => {
            Err(LexError { pos: 0, byte_pos: 0, ch: None, reason: LexErrorReason::TooLong })
        }
    }
}

pub const NUM_TERMINALS: usize = 36;
pub const NUM_NONTERMINALS: usize = 47;
pub const NUM_PRODUCTIONS: usize = 103;
pub const NUM_STATES: usize = 162;
const NONE: usize = 65535;
/// The augmented start production.
pub const AUG_PROD: usize = 102;

static TERM_NAMES: [&str; 36] = [
    "NAMESPACE", "ENTITY", "IN", "TYPE", "SET", "APPLIESTO", "PRINCIPAL", "ACTION", "RESOURCE",
    "CONTEXT", "ATTRIBUTES", "TAGS", "LONG", "STRING", "BOOL", "ENUM", "IDENTIFIER", "NUMBER",
    "STRINGLIT", "COMMA", "SEMICOLON", "COLON", "COLONCOLON", "LBRACE", "RBRACE", "LBRACKET",
    "RBRACKET", "LANGLE", "RANGLE", "EQUALS", "QUESTION", "AT", "LPAREN", "RPAREN", "EOF", "$",
];

static NONTERM_NAMES: [&str; 47] = [
    "schema", "namespace_list", "annotation", "annotation_list", "namespace", "namespace_body",
    "annotated_decl_list", "annotated_decl", "annotated_decl_bare", "decl", "entity",
    "opt_member_of", "opt_entity_body", "opt_eq", "opt_tags", "action", "opt_parents",
    "opt_applies_to", "opt_action_attrs", "type_decl", "app_decls", "app_decls_tail", "type",
    "opt_attr_decls", "attr_decls", "attr_decls_tail", "opt_question", "ident", "any_ident", "str",
    "eid", "name", "qual_name", "qual_tail", "path", "path_tail", "path_inline", "idents", "names",
    "qual_names", "eids", "principal_or_resource", "ent_types", "path_comma_list",
    "path_comma_tail", "qual_name_or_qual_names", "S'",
];

pub fn term_name(t: u16) -> &'static str {
    TERM_NAMES[t as usize]
}

pub fn nonterm_name(n: usize) -> &'static str {
    NONTERM_NAMES[n]
}

/// The left-hand side nonterminal of production `p`.
pub fn prod_lhs(p: usize) -> usize {
    LHS[p] as usize
}

/// The number of right-hand side symbols of production `p`.
pub fn prod_len(p: usize) -> usize {
    RHS_LEN[p] as usize
}

