impl<'a> Stacks<'a> {
    pub fn new() -> Self {
        Self::default()
    }

    /// Empty the stacks and give them a new lifetime, so that one set of buffers serves
    /// successive contexts (each parse borrows from its own `ctx`).
    pub fn recycle<'b>(mut self) -> Stacks<'b> {
        self.clear();
        // SAFETY: every stack is empty, so no value of lifetime `'a` remains; the two
        // types differ only in that lifetime and have the same layout.
        unsafe { std::mem::transmute::<Stacks<'a>, Stacks<'b>>(self) }
    }

    fn clear(&mut self) {
        self.entries.clear();
        self.v1.clear();
        self.v2.clear();
        self.v3.clear();
        self.v4.clear();
        self.v5.clear();
        self.v6.clear();
        self.v7.clear();
        self.v8.clear();
        self.v9.clear();
        self.v10.clear();
        self.v11.clear();
        self.v12.clear();
        self.v13.clear();
        self.v14.clear();
        self.v15.clear();
        self.v16.clear();
        self.v17.clear();
        self.v18.clear();
        self.v19.clear();
        self.v20.clear();
        self.v21.clear();
        self.v22.clear();
        self.v23.clear();
        self.v24.clear();
        self.v25.clear();
        self.v26.clear();
        self.v27.clear();
        self.v28.clear();
        self.v29.clear();
        self.v30.clear();
        self.v31.clear();
        self.v32.clear();
        self.v33.clear();
        self.v34.clear();
    }
}

/// Push the value a shifted token carries onto the stack of its type.
#[inline(always)]
fn push_payload<'a>(s: &mut Stacks<'a>, t: &Tok<'a>) {
    match t {
        Tok::IDENTIFIER(v) => s.v1.push(*v),
        Tok::NUMBER(v) => s.v2.push(*v),
        Tok::STRINGLIT(v) => s.v1.push(*v),
        #[allow(unreachable_patterns)]
        _ => {}
    }
}

